import React from 'react';
import './Shimmer.css'; // Make sure to create this CSS file

const Shimmer = () => {
    const shimmerCards = Array(6).fill(0); // Show 6 shimmer placeholders

    return (
        <div className="container mt-4">
            <div className="row g-4">
                {shimmerCards.map((_, index) => (
                    <div className="col-md-4" key={index}>
                        <div className="shimmer-card">
                            <div className="shimmer-img shimmer-animate"></div>
                            <div className="shimmer-title shimmer-animate"></div>
                            <div className="shimmer-category shimmer-animate"></div>
                            <div className="shimmer-price shimmer-animate"></div>
                        </div>
                    </div>
                ))}
            </div>
        </div>
    );
};

export default Shimmer;
